function calculateFee(type: string, amount: number) {
  switch (type) {
    case 'standard':
      return amount * 0.02;
    case 'premium':
      return amount * 0.015;
    case 'vip':
      return amount * 0.01;
    default:
      throw new Error('Unknown type');
  }
}

